1. Snow Metamorphism and Densification Model
The densification model tracks old and new snow layers separately: - Old snow density approaches ρ_max via exponential decay - New snow density uses the temperature-dependent equation: ρ = 50 + 1.7 × (T + 15)^(3/2)

rho_max     &lt;- 350   # kg/m³ — maximum density (from SNOTEL observations)
k           &lt;- 0.01  # densification rate (per hour)
density_old &lt;- 250   # kg/m³ — initial old snow density
depth_old   &lt;- 0
depth_new   &lt;- 0
density_new &lt;- 0

depth_total   &lt;- numeric(nrow(asos_data))
density_total &lt;- numeric(nrow(asos_data))

new_snow_density &lt;- function(temp_C) {
  pmax(50, pmin(400, 50 + 1.7 * (temp_C + 15)^(3/2)))
}

for (i in seq_len(nrow(asos_data))) {
  temp_C     &lt;- asos_data$temp_C[i]
  snowfall_m &lt;- asos_data$snowfall_m[i]

  density_old &lt;- rho_max - (rho_max - density_old) * exp(-k)
  depth_old   &lt;- depth_old * density_old / (density_old + k * depth_old)

  if (!is.na(temp_C) && !is.na(snowfall_m) && snowfall_m &gt; 0) {
    density_new &lt;- new_snow_density(temp_C)
    depth_new   &lt;- depth_new + snowfall_m * 100  # convert m → cm
  }

  total_depth &lt;- depth_old + depth_new
  depth_total[i] &lt;- total_depth
  if (total_depth &gt; 0) {
    density_total[i] &lt;- (depth_old * density_old + depth_new * density_new) / total_depth
  } else {
    density_total[i] &lt;- density_old
  }

  if (!is.na(snowfall_m) && snowfall_m &gt; 0) {
    depth_old   &lt;- depth_total[i]
    density_old &lt;- density_total[i]
    depth_new   &lt;- 0
    density_new &lt;- 0
  }
}

asos_data$modeled_depth_cm   &lt;- depth_total
asos_data$modeled_density    &lt;- density_total

asos_data &lt;- asos_data %&gt;%
  mutate(
    snowfall_cm        = snowfall_m * 100,
    cumulative_snowfall_cm = cumsum(snowfall_cm)
  )
